"use client";
import {CashierDepositLedgerReview} from './cashier-deposit-ledger-review';
import {useEffect,useRef,useState} from 'react';
import {hotelClient,hotelRpc,usd,type Membership} from '@/lib/pilot';
import {CashierDepositAccountAssign} from './cashier-deposit-account-assign';
import {CashierBankAccountCreate} from './cashier-bank-account-create';
import {CashierBankDepositVoid} from './cashier-bank-deposit-void';
import {CashierBankDepositCreate} from './cashier-bank-deposit-create';
import {readBankDeposits} from '@/lib/cashier-bank-deposits';
import {CashierBankReconciliation} from './cashier-bank-reconciliation';
export function CashierBankDeposits({membership}:{membership:Membership}){return <><Register key={[membership.tenant_id,membership.property_id,membership.role].join(':')} membership={membership}/><CashierBankReconciliation membership={membership}/></>}
function Register({membership}:{membership:Membership}){
 const [page,setPage]=useState<ReturnType<typeof readBankDeposits>|null>(null),[busy,setBusy]=useState(false),[error,setError]=useState(''),[actor,setActor]=useState('');const alive=useRef(false),lock=useRef(false);
 useEffect(()=>{alive.current=true;return()=>{alive.current=false}},[]);
 async function load(next=false){if(lock.current)return;lock.current=true;setBusy(true);setError('');try{
  const user=await hotelClient().auth.getUser();if(user.error||!user.data.user)throw Error('Sign in to view deposits.');const id=user.data.user.id;if(next&&actor!==id)throw Error('Sign-in changed. Refresh deposits.');const before=next?page?.next:null;if(next&&!before)return;
  const value=await hotelRpc('cashier_bank_deposits',{p_tenant:membership.tenant_id,p_property:membership.property_id,p_before:before??null});const result=readBankDeposits(value,{tenant:membership.tenant_id,property:membership.property_id,actor:id},before??null);
  const again=await hotelClient().auth.getUser();if(again.error||again.data.user?.id!==id)throw Error('Sign-in changed. Refresh deposits.');if(alive.current){setActor(id);setPage(result)}
 }catch(e){if(alive.current){setPage(null);setError(e instanceof Error?e.message:'Unable to load deposits.')}}finally{lock.current=false;if(alive.current)setBusy(false)}}
 return <section className="card"><h2>Bank deposit register</h2>{actor&&(membership.role==='owner'||membership.role==='manager')&&<CashierBankAccountCreate key={"bank-account:"+actor} scope={{tenant:membership.tenant_id,property:membership.property_id,actor}} onSaved={()=>void load()}/>}{actor&&<CashierBankDepositCreate key={"bank-deposit:"+actor} scope={{tenant:membership.tenant_id,property:membership.property_id,actor}} onSaved={()=>void load()}/>}<p>Recorded deposit slips await bank reconciliation. These declarations do not confirm bank receipt or post accounting entries. Refresh to include new submissions.</p><button disabled={busy} onClick={()=>void load()}>Refresh bank deposits</button>{error&&<p role="alert">{error}</p>}{page&&<>{page.entries.length?<div className="pilot-table-wrap"><table className="pilot-table"><thead><tr><th>Deposit date</th><th>Bank</th><th>Slip reference</th><th>Amount</th><th>Status</th><th>Submitted by</th><th>Cash sources</th><th>Actions</th></tr></thead><tbody>{page.entries.map(d=><tr key={d.id}><td>{d.date}</td><td>{d.accountLabel??d.bank}{!d.accountId&&<p>Account assignment needed</p>}{d.accountLabel&&d.accountLabel!==d.bank&&<p>Original nickname: {d.bank}</p>}</td><td>{d.reference}</td><td>{usd(Number(d.total))}</td><td>{d.status==='voided'?<>Voided<p>{d.voidReason}</p></>:'Awaiting bank reconciliation'}</td><td>{d.actor===actor?'You':d.actor}</td><td><details><summary>{d.allocations.length} cash source{d.allocations.length===1?'':'s'}</summary><p>{d.reason}</p><ul>{d.allocations.map(a=><li key={a.handoff??a.session}>{a.session?'Drawer '+a.session:'Handoff '+a.handoff}: {usd(Number(a.amount))}</li>)}</ul><p>Deposit reference: {d.id}</p></details></td><td>{(membership.role==='owner'||membership.role==='manager')&&<>{d.accountId&&d.status!=='voided'&&<CashierDepositLedgerReview key={'ledger:'+actor+':'+d.id+':'+d.accountId} scope={{tenant:membership.tenant_id,property:membership.property_id,actor}} deposit={d.id} bank={d.accountId} amount={d.total}/>}<CashierDepositAccountAssign key={'assign:'+actor+':'+d.id} scope={{tenant:membership.tenant_id,property:membership.property_id,actor}} deposit={d.id} assigned={!!d.accountId} onSaved={()=>void load()}/><CashierBankDepositVoid key={actor+':'+d.id} scope={{tenant:membership.tenant_id,property:membership.property_id,actor}} deposit={d.id} voided={d.status==='voided'} onSaved={()=>void load()}/></>}</td></tr>)}</tbody></table></div>:<p>No bank deposits on this page.</p>}{page.next&&<button disabled={busy} onClick={()=>void load(true)}>Next deposit page</button>}</>}</section>
}
